function startMotor(){if(!simulationOpen||simulationTab!=='motors')openSimulation('motors');stabilityUI?.stop();stopController();stopPhysics();if(motorRunning)return;const drive=motorDrive(model,motorId);if(!drive.ready){toast(drive.reason);return;}if(definition(model.parts.find(p=>p.id===motorId)).springMotor)motorDirection=1;motorBaseline=exportModel(model);motorRunning=true;motorAngle=0;updateMotorPanel();needsRender=true;}
