 const ports=!d.yClip&&(d.bores&&mode==='through'||mode==='wedge'&&hasRecesses(d)||d.motor&&mode==='mount'||(d.group==='rods'||d.flexi)&&mode==='end'||d.slots.length&&['end','side'].includes(mode));
 root.innerHTML=`<div class="placement-modes">${modes.map(k=>`<button data-placement-mode="${k}" title="${labels[k]} · C cycles connection" aria-label="${labels[k]}" aria-pressed="${mode===k}" class="${mode===k?'active':''}">${icon(modeIcon[k])}<span>${shortLabels[k]}</span></button>`).join('')}</div><div class="placement-adjust"><span class="placement-shortcut">C <span>connection</span></span>${ports?`<button data-placement-action="port" title="Next ${d.group==='rods'?'rod end':'socket'} (Tab)">${icon('port')}<span>${mode==='wedge'?'Recess '+(Math.floor(portIndex/2)+1)+(portIndex%2?' · back':' · front'):(d.bores&&mode==='through'?'Bore':d.group==='rods'?'End':d.motor?'Face':'Socket')+' '+(portIndex+1)}</span><kbd>Tab</kbd></button>`:''}${['wedge','worm'].includes(mode)?'':`<button data-placement-action="rotate" title="Rotate 45° (R). Middle-drag for direct rotation.">${icon('rotate')}<span>Rotate</span><kbd>R</kbd></button>`}<button data-placement-action="finish" title="Finish placing (Esc)" aria-label="Finish placing">${icon('close')}</button></div>${socketPicker(d)}`;
 root.querySelectorAll('[data-socket]').forEach(b=>b.onclick=()=>{portIndex=Number(b.dataset.socket);renderInspector();refreshGhost();});
