function chooseType(value,{straight=false}={}){partLibrary.close();if(BY_ID[value].trackJoiner){openPathBuilder('track','track-orange');return;}if(BY_ID[value].belt){openBeltBuilder();return;}if(!straight&&(BY_ID[value].tubing||BY_ID[value].flexi)){openPathBuilder(BY_ID[value].flexi?'flexi':'track',value);return;}if(simulationOpen)openSimulation(simulationTab,false);type=value;selected=null;moving=null;movingIds=null;roll=0;offset=0;portIndex=0;clearGhost();const d=BY_ID[type];if(!supportsMode(d,mode)||mode==='free'&&model.parts.length||d.group==='gears'||d.group==='wheels'||d.group==='extras'||d.motor)mode=defaultMode(d);setTool('build');renderCatalog();renderModelTree();updateOutline();if(matchMedia('(max-width:600px)').matches)togglePanel('library',false);}
