function pointerRay(e){const b=renderer.domElement.getBoundingClientRect();ray.setFromCamera(new T.Vector2((e.clientX-b.left)/b.width*2-1,-(e.clientY-b.top)/b.height*2+1),camera);}
function grabVector(e){pointerRay(e);const v=new T.Vector3();if(!ray.ray.intersectPlane(physicsGrab.plane,v))return null;v.sub(V(physicsBody.origin));return v.addScaledVector(V(physicsBody.axis),-v.dot(V(physicsBody.axis))).normalize();}
renderer.domElement.addEventListener('pointerdown',e=>{
 if(!physicsBody||e.button!==0)return;pointerRay(e);const hit=ray.intersectObjects(partsGroup.children,true).find(h=>physicsBody.ids.has(h.object.userData.partId)&&visiblePart(model,h.object.userData.partId,isolated));if(!hit)return;
 if(physicsBody.kind==='hinge-system'){e.preventDefault();e.stopImmediatePropagation();lastDown=null;controls.enabled=false;physicsGrab={system:true,plane:new T.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new T.Vector3()),hit.point),pointerId:e.pointerId};beginHingeGrab(physicsBody,hit.object.userData.partId,hit.point.toArray());renderer.domElement.setPointerCapture(e.pointerId);renderer.domElement.style.cursor='grabbing';updatePhysicsPanel();return;}
 const normal=V(physicsBody.axis);if(Math.abs(ray.ray.direction.dot(normal))<.08){toast('Orbit slightly to see the swing from the side before dragging.');return;}
 e.preventDefault();e.stopImmediatePropagation();lastDown=null;controls.enabled=false;const plane=new T.Plane().setFromNormalAndCoplanarPoint(normal,hit.point);physicsGrab={plane,startAngle:physicsBody.angle,previous:null,pointerId:e.pointerId};physicsGrab.previous=grabVector(e);holdBody(physicsBody);dragBody(model,physicsBody,physicsBody.angle,e.timeStamp/1000);renderer.domElement.setPointerCapture(e.pointerId);renderer.domElement.style.cursor='grabbing';updatePhysicsPanel();
 },true);
renderer.domElement.addEventListener('pointermove',e=>{if(!physicsGrab||!physicsBody)return;e.preventDefault();e.stopImmediatePropagation();if(physicsGrab.system){pointerRay(e);const p=V();if(ray.ray.intersectPlane(physicsGrab.plane,p))moveHingeGrab(physicsBody,p.toArray());return;}const next=grabVector(e);if(next&&physicsGrab.previous){const delta=Math.atan2(V(physicsBody.axis).dot(physicsGrab.previous.clone().cross(next)),physicsGrab.previous.dot(next));dragBody(model,physicsBody,physicsBody.angle+delta,e.timeStamp/1000);physicsGrab.previous=next;syncPartTransforms();}},true);
function endPhysicsGrab(cancel=false,time=performance.now()/1000){if(!physicsGrab||!physicsBody)return;const id=physicsGrab.pointerId;if(physicsGrab.system){endHingeGrab(physicsBody,cancel);applyHingeSystem(model,physicsBody);}else{if(cancel){physicsBody.angle=physicsGrab.startAngle;applyBody(model,physicsBody);}releaseBody(physicsBody,time,cancel);}physicsGrab=null;controls.enabled=true;renderer.domElement.style.cursor='grab';if(renderer.domElement.hasPointerCapture(id))renderer.domElement.releasePointerCapture(id);syncPartTransforms();updatePhysicsPanel();}
for(const event of['pointerup','pointercancel'])renderer.domElement.addEventListener(event,e=>{if(!physicsGrab)return;e.preventDefault();e.stopImmediatePropagation();endPhysicsGrab(event==='pointercancel',e.timeStamp/1000);},true);
// Pointer-based dragging works with mouse, pen and touch without a native drag image.
function eventPoint(e){const b=renderer.domElement.getBoundingClientRect();return new T.Vector2((e.clientX-b.left)/b.width*2-1,-(e.clientY-b.top)/b.height*2+1);}
function overWorkspace(e){const hit=document.elementFromPoint(e.clientX,e.clientY);return hit===renderer.domElement||!!hit?.closest('.motion-gizmo');}
function finishCatalogDrag(cancel=false,e=null){const d=catalogDrag;if(!d)return;catalogDrag=null;$('#drop-hint').hidden=true;document.body.classList.remove('part-dragging');controls.enabled=true;lastDown=null;
 if(!d.active)return;
 let placed=false;if(!cancel&&e&&overWorkspace(e)&&proposal&&!proposal.conflicts?.length)placed=commitProposal();
 if(!placed){const blocked=proposal?.conflicts?.length;clearGhost();toast(cancel?'Placement cancelled.':blocked?'Drop blocked. Choose a clear socket or floor position.':'Nothing placed. Drop inside the workspace.');}
 setTool('select');renderCatalog();
}
document.addEventListener('pointerdown',e=>{const card=e.target.closest('#catalog [data-part],#part-flyout [data-part]');if(!card||e.button!==0)return;catalogDrag={type:card.dataset.part,x:e.clientX,y:e.clientY,pointerId:e.pointerId,active:false,alt:e.altKey};});
document.addEventListener('dragstart',e=>{if(e.target.closest('#catalog,#part-flyout'))e.preventDefault();});
document.addEventListener('pointermove',e=>{const d=catalogDrag;if(!d||e.pointerId!==d.pointerId)return;if(!d.active&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<7)return;e.preventDefault();e.stopImmediatePropagation();
 if(!d.active){if(BY_ID[d.type].trackJoiner){catalogDrag=null;openPathBuilder('track','track-orange');return;}if(BY_ID[d.type].belt){catalogDrag=null;openBeltBuilder();return;}if(BY_ID[d.type].tubing){catalogDrag=null;openPathBuilder('track',d.type);return;}d.active=true;chooseType(d.type,{straight:true});controls.enabled=false;document.body.classList.add('part-dragging');}
 d.alt=e.altKey;pointerInside=overWorkspace(e);if(pointerInside){updatePointer(eventPoint(e));$('#drop-hint').textContent=proposal?.conflicts?.length?'Blocked · move to a clear position':proposal?.link?'Release to connect · C changes connection · R rotates':'Release to place · R rotates · Esc cancels';}else{clearGhost();$('#drop-hint').textContent='Drag into the workspace · Esc cancels';}$('#drop-hint').hidden=false;
},true);
document.addEventListener('pointerup',e=>{if(catalogDrag?.active){e.preventDefault();e.stopImmediatePropagation();finishCatalogDrag(false,e);}else catalogDrag=null;},true);
document.addEventListener('pointercancel',()=>finishCatalogDrag(true),true);
document.addEventListener('click',e=>{if(document.body.classList.contains('part-dragging')){e.preventDefault();e.stopImmediatePropagation();}},true);
function finishDirectDrag(cancel=false){const d=directDrag;if(!d)return;directDrag=null;controls.enabled=true;lastDown=null;
 if(d.active){if(cancel||d.blocked){model=parseModel(d.before);if(d.blocked&&!cancel)toast('Move blocked by another part. Original position restored.');}else if(exportModel(model)!==d.before){history.push(d.before);if(history.length>80)history.shift();future=[];toast(d.links?'Connected at matching endpoints.':'Assembly moved.');}update();}
 renderer.domElement.style.cursor='grab';$('#drop-hint').hidden=true;setHint();
 if(renderer.domElement.hasPointerCapture(d.pointerId))renderer.domElement.releasePointerCapture(d.pointerId);
}
document.addEventListener('pointerdown',e=>{
 if(unified?.active||e.target!==renderer.domElement||e.button!==0||e.shiftKey||tool!=='select'||driveView||controllerRunning||tippingActive||physicsBody||$('#dialog').open)return;
 pointerRay(e);const hit=pickableHits()[0];if(!hit)return;const id=hit.object.userData.partId;
 e.preventDefault();e.stopImmediatePropagation();lastDown=null;
 if(!selection.has(id)||e.altKey)selectIds(e.altKey?[id]:groupFor(model,id)?.partIds||[id]);
 stopMotor();stabilityUI?.stop();const plan=selectionMotionPlan(model,selection,'move'),reason=editBlockReason(model,plan.ids);
 if(reason){toast(reason+(groundedParts(model,selection).length?' Unlock the selected support before moving.':' Use Disconnect to move only this selection.'));return;}
 const normal=camera.getWorldDirection(new T.Vector3()),plane=new T.Plane().setFromNormalAndCoplanarPoint(normal,hit.point);
 directDrag={pointerId:e.pointerId,x:e.clientX,y:e.clientY,point:hit.point.clone(),plane,plan,before:exportModel(model),active:false,blocked:false};controls.enabled=false;renderer.domElement.setPointerCapture(e.pointerId);
},true);
document.addEventListener('pointermove',e=>{const d=directDrag;if(!d||d.pointerId!==e.pointerId)return;e.preventDefault();e.stopImmediatePropagation();if(!d.active&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<5)return;d.active=true;pointerRay(e);const point=new T.Vector3();if(!ray.ray.intersectPlane(d.plane,point))return;const delta=point.sub(d.point);model=parseModel(d.before);
 try{if(d.plan.kind==='ball'){pointBallToward(model,selected,d.point.toArray(),d.point.clone().add(delta).toArray());d.blocked=false;d.links=0;$('#drop-hint').textContent='Rotate about ball joint · Esc cancels';}
 else if(d.plan.kind==='axle'){let distance=delta.dot(V(d.plan.axis));if(e.shiftKey)distance=Math.round(distance/5)*5;const result=moveOnAxle(model,selected,{distance});d.blocked=false;d.links=0;$('#drop-hint').textContent=`Slide ${result.distance.toFixed(1)} mm${result.blockedBy?' · stopped at obstruction':''} · Esc cancels`;}
 else{const scale=camera.isPerspectiveCamera?2*camera.position.distanceTo(V(d.plan.origin))*Math.tan(camera.fov*DEG/2)/renderer.domElement.clientHeight:(camera.top-camera.bottom)/camera.zoom/renderer.domElement.clientHeight;const result=translatedSelection(model,d.plan.ids,delta.toArray(),{grid:e.shiftKey?5:0,magnet:e.altKey?0:Math.min(15,scale*16)});model=result.model;d.blocked=!!result.blocked.length;d.links=result.links.length;$('#drop-hint').textContent=d.blocked?'Blocked · release restores the original position':d.links?'Release to connect · Alt skips snapping':`${d.plan.ids.size} parts · drag in view plane · Shift: 5 mm · Esc cancels`;}
 renderer.domElement.style.cursor=d.blocked?'not-allowed':'grabbing';syncPartTransforms();$('#drop-hint').hidden=false;
 }catch(error){model=parseModel(d.before);d.blocked=true;$('#drop-hint').textContent=error.message;}
},true);
document.addEventListener('pointerup',e=>{if(!directDrag)return;e.preventDefault();e.stopImmediatePropagation();finishDirectDrag(false);},true);
document.addEventListener('pointercancel',()=>finishDirectDrag(true),true);
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&(catalogDrag||directDrag)){e.preventDefault();e.stopImmediatePropagation();finishCatalogDrag(true);finishDirectDrag(true);}else if(catalogDrag?.active&&['r','R'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(mode==='wedge')return;roll=(roll+(e.shiftKey?-45:45))%360;updatePointer(lastMouse);}},true);
window.addEventListener('blur',()=>{finishCatalogDrag(true);finishDirectDrag(true);});

function resize(){const{width,height}=$('#viewport').getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;if(camera.isOrthographicCamera){const s=camera.userData.size;camera.left=-s*camera.aspect/2;camera.right=s*camera.aspect/2;camera.top=s/2;camera.bottom=-s/2;}camera.updateProjectionMatrix();needsRender=true;}
new ResizeObserver(resize).observe($('#viewport'));
function fit(){const box=new T.Box3();for(const g of partsGroup.children)if(g.visible)box.union(new T.Box3().setFromObject(g));if(box.isEmpty()){const dir=camera.position.clone().sub(controls.target).normalize();controls.target.set(0,20,0);camera.position.copy(controls.target).addScaledVector(dir,camera.isOrthographicCamera?900:240);if(camera.isOrthographicCamera){camera.userData.size=200;resize();}}else{const center=box.getCenter(new T.Vector3()),size=box.getSize(new T.Vector3()),max=Math.max(size.x,size.y,size.z,60);const dir=camera.position.clone().sub(controls.target).normalize();controls.target.copy(center);if(camera.isPerspectiveCamera){const radius=box.getBoundingSphere(new T.Sphere()).radius,halfFov=Math.atan(Math.tan(camera.fov*DEG/2)*Math.min(camera.aspect,1)),dist=Math.max(60,radius)/Math.sin(halfFov)*1.1;camera.position.copy(center).addScaledVector(dir,dist);}else{camera.userData.size=max*1.35/Math.min(camera.aspect,1);camera.position.copy(center).addScaledVector(dir,900);resize();}}camera.lookAt(controls.target);controls.update();needsRender=true;}
function setView(view){$('#view-label').textContent={perspective:'Perspective',top:'Top view',front:'Front view',side:'Side view'}[view];const center=controls.target.clone();const pos=camera.position.clone();controls.dispose();if(view==='perspective'){camera=new T.PerspectiveCamera(36,1,.5,10000);camera.position.copy(center).add(V([420,310,480]));}else{camera=new T.OrthographicCamera(-300,300,300,-300,.1,10000);camera.userData.size=500;camera.position.copy(center).add(V({top:[0,900,.01],front:[0,0,900],side:[900,0,0]}[view]));}controls=new OrbitControls(camera,renderer.domElement);controls.target.copy(center);controls.enableDamping=true;controls.enableRotate=view==='perspective';controls.minDistance=30;controls.maxDistance=2400;controls.addEventListener('change',()=>needsRender=true);resize();fit();$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));clearGhost();}
function undo(){stabilityUI?.stop();stopPhysics();physicsBaseline=null;stopMotor();motorBaseline=null;if(!history.length)return;future.push(exportModel(model));model=parseModel(history.pop());selected=null;moving=null;clearGhost();update();setHint('Last change undone.');toast('Last change undone.');}
function redo(){stabilityUI?.stop();stopPhysics();physicsBaseline=null;stopMotor();motorBaseline=null;if(!future.length)return;history.push(exportModel(model));model=parseModel(future.pop());selected=null;moving=null;clearGhost();update();setHint('Last change restored.');}
function download(data,name,mime='application/json'){const blob=new Blob([data],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function loadExample(name){unified?.close();if(model.parts.length&&!backupCurrent())return false;repeatUI.close();snapshot();if(simulationOpen)openSimulation(simulationTab,false);isolated=null;selection.clear();collapsedLayers.clear();model=[...EXAMPLES,...REFERENCE_SCENES].some(e=>e.id===name)?createExample(name):name==='balance'?balanceModel():name==='gears'?gearDemo():name==='chain'?chainModel({count:24,closed:true}):name==='windmill'?windmillModel():exampleModel(name);if(!EXAMPLES.some(e=>e.id===name))prepareGroundedExample(model,name);motorId=model.parts.find(p=>definition(p).motor)?.id||null;selected=motorId&&EXAMPLES.find(e=>e.id===name)?.action==='motors'?motorDrive(model,motorId).shaftId||null:null;useMotorSpec();motorAngle=0;manipulation='auto';moving=null;setTool('select');update();renderCatalog();fit();if(model.editor?.groups.length||['square','balance','tower','compound','powered','windmill','swing','gears'].includes(name)){setLibraryView('model');for(const g of editorState(model).groups)collapsedLayers.add(g.id);renderModelTree();}if(name==='square'){selectIds(model.parts.map(p=>p.id));repeatUI.open();}const demo=EXAMPLES.find(e=>e.id===name);if(['hinges','motors'].includes(demo?.action))openSimulation(demo.action);if(demo?.hint)setHint(demo.hint);toast('Example loaded. Your previous model is in the local archive.');}
function inventory(){const counts=new Map();for(const p of model.parts)counts.set(p.type,(counts.get(p.type)||0)+1);showDialog(`<h2>Parts list</h2><p>${model.parts.length} parts in this model.</p><table><thead><tr><th>Part</th><th>Quantity</th></tr></thead><tbody>${[...counts].map(([t,n])=>`<tr><td>${BY_ID[t].name}${BY_ID[t].nominal?' · '+BY_ID[t].nominal+' mm':''}</td><td>${n}</td></tr>`).join('')}</tbody></table><button id="inventory-save" class="button">Download parts-list</button>`);$('#inventory-save').onclick=()=>download(['Part;Quantity',...[...counts].map(([t,n])=>`${BY_ID[t].name};${n}`)].join('\n'),'knex-parts-list.csv','text/csv;charset=utf-8');}
function help(){showDialog(`<h2>Controls</h2><p>Drag a part from Parts into the workspace. Near a green socket it snaps; elsewhere it rests on the placement floor. Release to place, or press Escape to cancel. Click a library part instead to place several copies. Drag existing parts to move their connected assembly; fixed supports stay protected. Shift gives 5 mm steps; Alt-click selects a single part inside a group. Disconnect first to move only that selection away.</p><p>Physics opens one shared solver for gravity, hinges, balls, collisions and tipping. Play runs it; Reset restores the start. Place ball gives a vertical drop preview and centers between nearby track rails. Locked parts support the build without moving; Bypass holds a rigid section without collisions or joints. Rigid assemblies freezes relative joint motion. Motor previews and Test drive remain separate prescribed-motion tools.</p><p>Choose a part from the library. Point at a green connection point to preview the placement, then click to attach it. Use “Free placement” to start a separate assembly.</p><h3>Locking and fixed supports</h3><p>Select the base and press G, or click Lock selection. Locked parts keep their world position and orientation during editing, motors and hinge physics. G again releases them. Amber outlines show fixed supports; cyan outlines show parts that will move. Layer locks protect editing only. Locking is saved with the model, and duplicates start free.</p><h3>Selection and scene organization</h3><p>Shift-click adds or removes a part. Shift-drag selects every part whose projected bounds touch the selection box, including partly covered rods. Double-click selects the connected assembly. Clicking a named group selects its members; Alt-click picks just the part. W shows move handles, E rotation handles, F frames the selection. Ctrl/Cmd G groups, Ctrl/Cmd Shift G ungroups, Ctrl/Cmd D duplicates, and H isolates the selection. Shift H shows the scene again.</p><p>The Scene tab contains layers with visibility and lock buttons, groups, and parts. Use + Layer to put selected parts on a layer. Double-click a group or layer name to rename it. Layer locks protect geometry, including connected neighbours. Groups and layers are saved with the model and can be undone. Grouping organizes selection; mechanical connections still determine which neighbours must move together.</p><h3>Fast placement and rotation</h3><p>Aim within 22 screen pixels of an available socket to snap. The current socket stays highlighted as you approach it. Tab cycles the socket on the new connector; Shift Tab cycles nearby targets. R rotates 45 degrees. Hold the middle mouse button and drag to rotate the preview without losing its snap. Shift gives 15-degree steps; Alt gives free rotation. Middle-drag on an existing connector pivots its connected branch around an available rod socket, or spins its axle group. In a closed rigid structure it rotates the connected assembly. Escape cancels the drag. Each completed drag is one undo step.</p><h3>Connections</h3><p>The floating workspace toolbar switches connection types. For connectors, click a numbered dot on the connector picture to choose the exact socket; a pink dot marks that opening in the placement preview. Parts under the pointer glow mint; selected parts stay fluorescent pink. While aiming or dragging, press C to cycle types (Shift-C reverses), Tab to change the rod end or connector socket, and R to rotate. Middle-drag rotates directly. Tab outside the canvas navigates controls normally.</p><ul><li><b>End:</b> rod ends snap into unused connector sockets. Matching sockets at the other end connect automatically.</li><li><b>Through-hole:</b> rods pass through the center hole. After placing, select a part and drag the gold arrow to slide or the gold ring to spin.</li><li><b>Side-on:</b> the ribbed side of a rod clips across a connector socket. This is unavailable for the short green rod.</li><li><b>3D interlock:</b> blue and purple connectors slide together at right angles.</li></ul><h3>Moving connected parts</h3><p>Select a part to show drag handles. Move model and Rotate model affect all connected parts. Axle motion moves the group held together by clips while loose center holes act as bearings. Drag the gold arrow to slide and the gold ring to spin. Hold Shift for 5 mm or 15° steps; Esc cancels a drag. Each drag is one undo step.</p><p>Through-hole connections can be marked “Move together” in the properties panel. This is an editor grouping constraint, not an added physical locking part. Side clips, end clips and 3D interlocks group automatically. Sliding respects rod length, coaxial bearings and solid obstructions. A continuous collision check stops a slide even when the pointer jumps past a part. Conservative geometry bounds can stop close-fitting pieces slightly early. Rotation is not collision-limited.</p><h3>Generators, gears and driving</h3><p>Generate builds fixed-length rod runs, extends an open socket, repeats selected sections with spacing and rotation, or makes chains. New copies retain their internal connections. Large chain links are static geometry, not a flexible chain simulation.</p><p>Gears &amp; chain contains 14-, 34- and 82-tooth parts reconstructed from supplier photos. Gear mesh joins parallel shafts; attach a tan drive clip (or use the push-on grey gear) to transmit motor rotation. The Two-stage gearbox example demonstrates ratio and direction. Tooth profiles and pitch distances are approximate. 90° gears connects a crown gear to a perpendicular axle using ideal pitch contact.</p><p>Controller lets you assign forward/reverse keys and a left, right, all-drive or auxiliary channel to each motor. Settings are saved with the model. Enable controls to run it on the bench. Test drive uses a separate copy in a circuit or slalom playground, preserving your build. The twin-motor rover steers through different wheel speeds. Arrow keys, on-screen buttons or a standard gamepad’s left stick control the drive channels. Space brakes; Escape stops. A single axle can drive straight but needs a second independently driven side to steer.</p><p>The playground uses approximate flat-ground tyre traction, acceleration and a conservative circular vehicle boundary against walls and obstacles. It does not simulate suspension, jumps, gears deforming or realistic tyre slip. <a href="https://shop.knexusergroup.org.uk/collections/knex-parts-gears" target="_blank" rel="noreferrer">Gear references</a>. GrabCAD files were inspected as references but are not imported: downloads require sign-in and scale needs verification.</p><h3>Gravity and swings</h3><p>Open Examples → Playground swing. Drag a hanging rod or the seat itself, then release it. Gravity pulls the assembly back, its momentum carries it past the resting position, and friction gradually slows it down. Hold it still before releasing for no added push. Pull &amp; release provides a keyboard-accessible alternative. Escape cancels a grab.</p><p>For your own build, select an assembly attached through a loose axle hole and open Simulate → Joints → Run hinge. Connected hinges move together, with locked supports held fixed. Pause keeps the pose; Reset restores the starting pose; undo restores the preceding run. Hinge simulation solves connected rigid groups and multiple axle joints together, including nested hinges. Locked groups stay fixed; if none is locked, the largest connected group is held fixed. Part masses and centers affect motion; shape inertia is approximate. Flexible parts, part-to-part contact and ground traction are not simulated in this mode.</p><p>The swing is a single-bay adaptation of the <a href="${SWING_REFERENCE}" target="_blank" rel="noreferrer">K’NEX User Group swing</a>, using the existing classic connector and hole-end clip variants. It is not an exact copy of the two-seat build.</p><h3>Navigation and shortcuts</h3><p>Drag the background to orbit, right-drag to pan and scroll to zoom. On a touchscreen, use one finger to orbit and two fingers to pan and zoom.</p><p><b>V</b> select · <b>B</b> place · <b>R</b> rotate · <b>F</b> fit to view · <b>Esc</b> stop placing · <b>⌘/Ctrl Z</b> undo · <b>Delete</b> remove selected part.</p><h3>Saving and restoring</h3><p>Your model is saved on this device. “Save” downloads an editable JSON file. “Open” imports that file. Creating a new model archives the current model first.</p><button class="button secondary" id="show-archive">Open local archive</button><h3>Geometry and accuracy</h3><p>This version includes classic rods, standard connectors and spacers. The geometry is reconstructed, not an official CAD library. Rod proportions, the 10.1 mm socket distance and 45° construction angles are based on K’NEX documentation. Plastic clip details and 3D interlock slots are approximations.</p><p>The editor checks occupied sockets and coarse overlaps between rods and between connector centers. Placement checks remain approximate. Clip tolerances, bending and traction are not simulated. Physics uses gravity, mass and approximate collision shapes for moving assemblies and balls. The blue 92840 and green 22722 enclosed motors are reconstructed from identified part photos, with ribbed battery cases, round gearboxes, reversing switches and coaxial mounting faces. Dimensions and clip tolerances remain unverified. Legacy placeholder motors remain readable in old files but are excluded from the part library. A tan drive clip is also available. Motor playback turns connected geometry at the selected preview speed; it does not calculate torque, battery load or swept collisions. Micro K’NEX and many specialty parts are not included.</p><h3>Classic racing wheels</h3><p>Racing hubs 91170, 91174 and 91184 attach to rod ends using End mode. They spin freely but do not slide through the rod. Narrow 91254 hubs use Through-hole mode. The wide 91160 tyre takes one 91184 hub or two narrow hubs, one in each half. Fit tyre offers only documented compatible parts. Examples → Part reference scenes → Racing wheels &amp; bearings shows these assemblies. Tread and slick tyres differ visually; tyre traction is still approximate.</p><h3>Wheels and the manual build</h3><p>Slide a hub onto an axle, then use Fit tyre to add a compatible tyre. Wheels turn freely until a tan drive clip keys the hub to the axle. Black snap caps retain parts at rod ends.</p><p>Examples → Wheeled chassis follows the illustrated guide’s axle stacks and four red chassis rails, using its permitted classic wheel and enclosed motor variants. Start motor rotates the driven front wheels. Use Test drive to run a separate copy on the flat-ground course.</p><p><a href="${VEHICLE_MANUAL}" target="_blank" rel="noreferrer">Wheeled Vehicle Base: illustrated assembly guide</a></p><h3>Motor mounting</h3><p>Choose a white 8-way connector and Motor mount to seat it on either fixed gearbox face. The drive rod passes through the aligned center holes. These face mounts stay still when the axle turns.</p><h3>Motor playback</h3><p>Open Examples → Motor windmill, then press Start motor. Space toggles playback; Reverse changes direction. The speed control sets preview RPM, not a measured hardware rating. The tan drive clip keys the hub to the axle. Removing it releases the hub; locking the rotor to the housing blocks playback. Editing pauses playback. Stop keeps the current pose; Reset pose restores the pose from the latest start.</p><h3>References</h3><ul><li><a href="https://www.knexusergroup.org.uk/en/knex-hint-M4.html" target="_blank" rel="noreferrer">Enclosed battery motor: shaft and mount reference</a></li><li><a href="https://www.knexusergroup.org.uk/en/knex-hint-W6.html" target="_blank" rel="noreferrer">Tan drive clip: transferring rotation to the hub</a></li><li><a href="https://www.basicfun.com/wp-content/uploads/2023/02/85049-325PC-Motorized-Creations-Core-Instructions.pdf" target="_blank" rel="noreferrer">Basic Fun: motorized building instructions</a></li><li><a href="https://patents.google.com/patent/US7666054B2/en" target="_blank" rel="noreferrer">K’NEX patent: dimensions and rod proportions</a></li><li><a href="https://www.basicfun.com/wp-content/uploads/2023/02/17010-Imagine-Builder-Basics.pdf" target="_blank" rel="noreferrer">Basic Fun: official building instructions</a></li><li><a href="https://www.knexusergroup.org.uk/en/knex-hint-A2.html" target="_blank" rel="noreferrer">K’NEX User Group: three rod connection methods</a></li><li><a href="https://www.knexusergroup.org.uk/en/knex-hint-A4.html" target="_blank" rel="noreferrer">K’NEX User Group: 3D connectors</a></li></ul><p>Independent building editor. K’NEX is a trademark of its respective owner. Built with Three.js.</p>`);$('#show-archive').onclick=archive;}
function archive(){let entries=[];try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k.startsWith(STORE+'-backup-')){try{const m=parseModel(localStorage.getItem(k));entries.push({key:k,model:m,time:Number(k.split('-').at(-1))});}catch{}}}}catch{toast('Local storage is unavailable.');return;}entries.sort((a,b)=>b.time-a.time);showDialog('<h2>Local archive</h2><p>Previous models on this device. Restoring a model archives the current one first.</p><div id="archive-list"></div>');if(!entries.length)$('#archive-list').textContent='The archive is empty.';for(const e of entries){const b=document.createElement('button');b.className='example-button';b.textContent=`${displayName(e.model.name)} · ${e.model.parts.length} parts · ${new Date(e.time).toLocaleString('en-GB')}`;b.onclick=()=>{if(!backupCurrent())return;snapshot();model=e.model;selected=null;setTool('select');update();fit();$('#dialog').close();};$('#archive-list').append(b);}}
function controllerBindings(){return model.controller?.length?model.controller:defaultBindings(model);}
function controllerDialog(){
 stopMotor();const motors=model.parts.filter(p=>definition(p).motor&&!definition(p).springMotor&&!definition(p).wormMotor);if(!motors.length){toast('Add a battery motor or load the Twin-motor rover example first.');return;}
 const bindings=controllerBindings(),keys=Array.from({length:26},(_,i)=>'Key'+String.fromCharCode(65+i)).concat(Array.from({length:10},(_,i)=>'Digit'+i));
 const options=key=>keys.map(k=>`<option value="${k}" ${k===key?'selected':''}>${k.replace('Key','').replace('Digit','')}</option>`).join('');
 showDialog(`<h2>Motor controller</h2><p>Assign each motor to keyboard buttons and a drive channel. Arrow keys and the on-screen pad mix forward/reverse with left/right steering.</p>${motors.map((p,i)=>{const b=bindings.find(b=>b.motorId===p.id)||defaultBindings(model)[i];return `<div class="controller-row"><strong>${definition(p).name}<br>#${model.parts.indexOf(p)+1}</strong><label>Channel<select data-channel="${i}">${['left','right','all','aux'].map(c=>`<option value="${c}" ${b.channel===c?'selected':''}>${{left:'Left drive',right:'Right drive',all:'Both sides',aux:'Auxiliary'}[c]}</option>`).join('')}</select></label><label>Forward<select data-forward="${i}">${options(b.forward)}</select></label><label>Reverse<select data-reverse="${i}">${options(b.reverse)}</select></label><label>Invert<input data-invert="${i}" type="checkbox" ${b.invert?'checked':''}></label></div>`;}).join('')}<p class="note">Mappings are saved with this model. Auxiliary motors respond only to their assigned keys. These are virtual controls for the simulation, not a connection to physical K’NEX hardware.</p><p id="mapping-error" role="status"></p><div class="action-row"><button id="mapping-save" class="button">Save mappings</button><button id="mapping-run" class="button">Enable controls</button></div>`);
 function save(run){const mapped=motors.map((p,i)=>({motorId:p.id,channel:$(`[data-channel="${i}"]`).value,forward:$(`[data-forward="${i}"]`).value,reverse:$(`[data-reverse="${i}"]`).value,invert:$(`[data-invert="${i}"]`).checked}));if(mapped.some(b=>b.forward===b.reverse)){$('#mapping-error').textContent='Choose different forward and reverse keys for each motor.';return;}snapshot();model.controller=mapped;update();$('#dialog').close();if(run)startController();else toast('Motor mappings saved with the model.');}
 $('#mapping-save').onclick=()=>save(false);$('#mapping-run').onclick=()=>save(true);
}
function showControlPanel(driving=false){document.body.classList.add('control-active');$('#control-panel').hidden=false;$('#control-title').textContent=driving?'Test drive':'Motor controller';$('#drive-reset').hidden=!driving;$('#drive-camera').hidden=!driving;$('#control-mappings').textContent=controllerBindings().map(b=>`${b.channel}: ${b.forward.replace('Key','').replace('Digit','')} / ${b.reverse.replace('Key','').replace('Digit','')}`).join(' · ');}
function startController(){stabilityUI?.stop();stopPhysics();stopMotor();controllerBaseline=exportModel(model);controllerRunning=true;selected=null;clearGhost();updateOutline();showControlPanel();$('#control-status').textContent='Ready. Hold a key or a controller button.';needsRender=true;}
function stopController(){if(!controllerRunning)return;controllerRunning=false;controlKeys.clear();padKeys.clear();if(controllerBaseline&&exportModel(model)!==controllerBaseline){history.push(controllerBaseline);future=[];}controllerBaseline=null;document.body.classList.remove('control-active');$('#control-panel').hidden=true;update();}
function enterPlayground(course){try{openSimulation(simulationTab,false);repeatUI.close();stopController();stopMotor();stopPhysics();const next=playgroundView(scene,model,course);driveCameraState={position:camera.position.clone(),target:controls.target.clone()};driveView=next;clearGhost();selected=null;updateOutline();partsGroup.visible=false;markerGroup.visible=false;ground.visible=false;grid.visible=false;originAxes.visible=false;document.body.classList.add('driving');$$('.topbar,.library,.inspector,.toolbar>*:not(#playground-tool)').forEach(e=>e.inert=true);$('#playground-tool').textContent='Back to build';showControlPanel(true);setView('perspective');controls.maxDistance=6500;controls.maxPolarAngle=Math.PI*.49;driveFollow=true;$('#drive-camera').textContent='Camera: follow';camera.position.set(driveView.state.x-420,430,driveView.state.z+620);controls.target.set(driveView.state.x,35,driveView.state.z);$('#view-label').textContent=course==='circuit'?'Circuit':'Slalom playground';setHint('Arrow keys: drive and steer · Space: brake · Escape: back to build');needsRender=true;}catch(e){toast(e.message);}}
function exitPlayground(){if(!driveView)return;driveView.dispose();driveView=null;controlKeys.clear();padKeys.clear();partsGroup.visible=true;markerGroup.visible=true;ground.visible=true;grid.visible=gridOn;originAxes.visible=true;$('#control-panel').hidden=true;document.body.classList.remove('driving','control-active');$$('.topbar,.library,.inspector,.toolbar>*:not(#playground-tool)').forEach(e=>e.inert=false);$('#playground-tool').textContent='Test drive';controls.maxDistance=2400;controls.maxPolarAngle=Math.PI*.94;if(driveCameraState){camera.position.copy(driveCameraState.position);controls.target.copy(driveCameraState.target);}update();setHint('Back in the editor. Your build was preserved.');}
function playgroundDialog(){if(driveView){exitPlayground();return;}showDialog('<h2>Test drive</h2><p>Drive a copy of your current model. The editor build stays unchanged.</p><div class="course-options"><button class="button" data-course="circuit">Circuit</button><button class="button" data-course="slalom">Slalom playground</button></div><p class="note">Flat-ground simulation with wheel-derived speed, differential steering, walls and obstacles. A conservative vehicle boundary prevents driving through barriers. No jumps or suspension yet.</p><p class="note">For a ready-to-drive build, choose Examples → Twin-motor rover.</p>');$$('[data-course]').forEach(b=>b.onclick=()=>{$('#dialog').close();enterPlayground(b.dataset.course);});}
function tickController(dt){if(!dt)return;const bindings=controllerBindings();let gamepad=null;try{const p=[...(navigator.getGamepads?.()||[])].find(p=>p?.connected&&p.mapping==='standard');if(p){const axis=i=>Math.abs(p.axes[i]||0)>.12?p.axes[i]:0;gamepad={throttle:-axis(1),steer:-axis(0)};}}catch{}
 const commands=motorCommands(bindings,controlKeys,{throttle:(padKeys.has('forward')?1:0)-(padKeys.has('reverse')?1:0),steer:(padKeys.has('left')?1:0)-(padKeys.has('right')?1:0),gamepad}),brake=controlKeys.has('Space')||padKeys.has('brake');
 try{if(driveView){driveView.step(dt,commands,{rpm:controlRpm,brake});const s=driveView.state;$('#control-status').textContent=`${s.blocked?'Obstacle: reverse to clear':'Driving'} · ${(Math.abs(s.v)/1000).toFixed(2)} m/s · ${(s.distance/1000).toFixed(2)} m · laps ${s.laps}`;if(driveFollow){const target=V([s.x,35,s.z]),delta=target.clone().sub(controls.target);camera.position.add(delta);controls.target.copy(target);}needsRender=true;}else{let active=0;for(const[id,value]of commands){if(brake||Math.abs(value)<.001)continue;stepMotor(model,id,dt,{rpm:Math.max(1,motorRate(model.parts.find(p=>p.id===id),controlRpm)*Math.abs(value)),direction:Math.sign(value)});active++;}$('#control-status').textContent=brake?'Braked':active?`${active} motor${active>1?'s':''} running`:'Ready. Hold a key or a controller button.';if(active)syncPartTransforms();}}catch(e){if(driveView)exitPlayground();else stopController();toast(e.message);}
}
