$('#drive-camera').onclick=()=>{driveFollow=!driveFollow;$('#drive-camera').textContent='Camera: '+(driveFollow?'follow':'overview');if(!driveFollow){camera.position.set(0,4000,3200);controls.target.set(0,0,0);}else if(driveView){camera.position.set(driveView.state.x-420,430,driveView.state.z+620);controls.target.set(driveView.state.x,35,driveView.state.z);}needsRender=true;};
for(const b of $$('[data-drive]')){b.onpointerdown=e=>{e.preventDefault();padKeys.add(b.dataset.drive);b.classList.add('held');b.setPointerCapture(e.pointerId);};for(const ev of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>{padKeys.delete(b.dataset.drive);b.classList.remove('held');});}
window.addEventListener('keydown',e=>{if(!driveView&&!controllerRunning)return;if(['SELECT','TEXTAREA'].includes(e.target.tagName)||e.target.tagName==='INPUT'&&e.target.type!=='range')return;if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.code==='Escape'){e.preventDefault();driveView?exitPlayground():stopController();return;}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space',...controllerBindings().flatMap(b=>[b.forward,b.reverse])].includes(e.code)){e.preventDefault();controlKeys.add(e.code);}},true);
