function syncSelection(){if(!selected)selection.clear();else if(!selection.has(selected))selection=new Set([selected]);selection=new Set([...selection].filter(id=>model.parts.some(p=>p.id===id)&&selectablePart(model,id,isolated)));if(!selection.has(selected))selected=[...selection][0]||null;return selection;}
function selectIds(ids,event={}){stabilityUI?.stop();if(tool!=='select')setTool('select');stopMotor();stopPhysics();const valid=ids.filter(id=>selectablePart(model,id,isolated));if(event.shiftKey){for(const id of valid)selection.has(id)?selection.delete(id):selection.add(id);}else selection=new Set(valid);selected=[...selection][0]||null;manipulation='auto';renderInspector();updateOutline();renderModelTree();renderCatalog();needsRender=true;}
function sceneRename(kind,id){const item=editorState(model)[kind==='layer'?'layers':'groups'].find(x=>x.id===id);if(!item)return;nameDialog('Rename '+kind,item.name,value=>{snapshot();item.name=value;update();});}
function nameDialog(title,initial,accept){showDialog(`<h2>${title}</h2><label class="field"><span>Name</span><input id="scene-name-input" maxlength="60"></label><button class="button" id="scene-name-save">Save</button>`);$('#scene-name-input').value=initial;const save=()=>{const name=$('#scene-name-input').value.trim();if(!name)return;$('#dialog').close();accept(name);};$('#scene-name-save').onclick=save;$('#scene-name-input').onkeydown=e=>{if(e.key==='Enter')save();};$('#scene-name-input').focus();$('#scene-name-input').select();}
function groupSelection(){const ids=[...syncSelection()];if(!ids.length){toast('Shift-click parts to select them first.');return;}nameDialog('Group selection','Group '+(editorState(model).groups.length+1),name=>{snapshot();makeGroup(model,ids,name);update();setLibraryView('model');toast('Group created. Double-click its name to rename.');});}
function layerSelection(){const ids=[...syncSelection()];nameDialog('New layer','Layer '+(editorState(model).layers.length+1),name=>{snapshot();makeLayer(model,ids,name);update();setLibraryView('model');toast(ids.length?'Selected parts moved to the new layer.':'Empty layer created. Select parts and use Move to layer to fill it.');});}
function ungroupSelection(){const ids=syncSelection(),e=editorState(model);if(!e.groups.some(g=>g.partIds.some(id=>ids.has(id))))return;snapshot();e.groups=e.groups.filter(g=>!g.partIds.some(id=>ids.has(id)));update();toast('Selection ungrouped. Mechanical connections are unchanged.');}
function isolateSelection(){if(isolated){isolated=null;}else{const ids=syncSelection();if(!ids.size)return;isolated=new Set(ids);}renderParts();renderMarkers();renderModelTree();renderInspector();$('#isolate-selection').classList.toggle('active',!!isolated);needsRender=true;}
function frameSelection(){const ids=syncSelection();if(!ids.size){fit();return;}const box=groupBounds(ids);if(box.isEmpty())return;const center=box.getCenter(new T.Vector3()),radius=Math.max(30,box.getBoundingSphere(new T.Sphere()).radius),dir=camera.position.clone().sub(controls.target).normalize();controls.target.copy(center);if(camera.isPerspectiveCamera){const half=Math.atan(Math.tan(camera.fov*DEG/2)*Math.min(camera.aspect,1));camera.position.copy(center).addScaledVector(dir,radius/Math.sin(half)*1.25);}else{camera.userData.size=radius*2.5/Math.min(camera.aspect,1);camera.position.copy(center).addScaledVector(dir,900);resize();}controls.update();needsRender=true;}
