 renderGroundPanel(root);
 $$('[data-multi-mode]').forEach(b=>b.onclick=()=>{manipulation=b.dataset.multiMode;renderInspector();updateOutline();needsRender=true;});$('#multi-group').onclick=groupSelection;$('#multi-ungroup').onclick=ungroupSelection;$('#multi-layer').onclick=layerSelection;$('#multi-isolate').onclick=isolateSelection;$('#multi-frame').onclick=frameSelection;$('#multi-duplicate').onclick=duplicatePicked;
 const layers=editorState(model).layers;if(layers.length){const label=document.createElement('label');label.className='field';label.append(document.createTextNode('Move selected parts to layer'));const sel=document.createElement('select');const opt=document.createElement('option');opt.textContent='Choose a layer';opt.value='';sel.append(opt);layers.forEach((l,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=l.name;sel.append(o);});sel.onchange=()=>{if(sel.value==='')return;const layer=layers[Number(sel.value)],picked=[...ids];snapshot();for(const l of layers)l.partIds=l.partIds.filter(id=>!ids.has(id));layer.partIds.push(...picked);update();};label.append(sel);root.append(label);}
