function pickableHits(){return ray.intersectObjects(partsGroup.children,true).filter(h=>h.object.userData.partId&&selectablePart(model,h.object.userData.partId,isolated));}

function toggleGrounding(value){if(middleDrag||boxDrag)cancelEditorDrag();gizmo?.cancel();const ids=new Set(syncSelection());if(!ids.size){toast('Select a support or base first.');return;}const ground=value??groundedParts(model,ids).length!==ids.size;snapshot();setGrounded(model,ids,ground);manipulation='auto';update();toast(ground?'Selection locked. Its position and orientation are fixed.':'Selection unlocked. Its joints still constrain movement.');}
function renderGroundPanel(root){
 const ids=new Set(syncSelection()),count=groundedParts(model,ids).length,plan=motionIntent(),reason=plan?editBlockReason(model,plan.ids):'',all=count===ids.size,panel=document.createElement('div');panel.className='ground-panel compact-ground';panel.classList.toggle('is-grounded',!!count||!!reason);
 panel.innerHTML=`<button class="ground-state" aria-pressed="${all}" title="${all?'Unlock':'Lock'} selection (G)">${icon(all?'ground':'unlock')}<span>${all?'Locked':count?'Partly locked':'Unlocked'}</span><kbd>G</kbd></button>${reason?'<button class="find-supports" title="Select the fixed supports blocking this movement" aria-label="Select fixed supports">'+icon('frame')+'</button>':'<span class="motion-count" title="Parts affected by the current movement">'+(plan?.ids.size||0)+' move</span>'}`;
 panel.querySelector('.ground-state').onclick=()=>toggleGrounding();if(reason){panel.title=reason;const inspect=panel.querySelector('.find-supports');inspect.onclick=()=>{selectIds(groundedParts(model,selectionClosure(model,ids)).map(p=>p.id));setLibraryView('model');};inspect.disabled=!groundedParts(model,selectionClosure(model,ids)).length;const state=document.createElement('span');state.className='blocked-caption';state.textContent=all?'Fixed in place':'Movement blocked by fixed supports';panel.append(state);}
 root.prepend(panel);
}
