$('#project-name').onchange=e=>{snapshot();model.name=e.target.value.trim()||'My model';update();};
$('#new').onclick=()=>{if(!backupCurrent())return;snapshot();model=emptyModel();isolated=null;selected=null;moving=null;type='c-white';mode='free';setTool('build');update();renderCatalog();fit();toast('Empty workspace. Your previous model is in the local archive.');};
$('#open').onclick=()=>$('#file-input').click();$('#file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>4e6)throw Error('File is too large (maximum 4 MB).');const next=parseModel(await file.text());if(!backupCurrent())return;snapshot();model=next;isolated=null;selected=null;moving=null;setTool('select');update();renderCatalog();fit();toast('Model opened.');}catch(err){toast(err.message||'This file could not be opened.');}e.target.value='';};
window.addEventListener('keydown',e=>{if(unified?.active||driveView||controllerRunning)return;if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)||$('#dialog').open)return;const key=e.key.toLowerCase();if(key==='escape'&&(middleDrag||boxDrag)){cancelEditorDrag();return;}if((e.metaKey||e.ctrlKey)&&key==='g'){e.preventDefault();e.shiftKey?ungroupSelection():groupSelection();return;}if((e.metaKey||e.ctrlKey)&&key==='d'){e.preventDefault();duplicatePicked();return;}if((e.metaKey||e.ctrlKey)&&key==='a'){e.preventDefault();selectIds(model.parts.filter(p=>selectablePart(model,p.id,isolated)).map(p=>p.id));return;}if(key==='g'&&!e.metaKey&&!e.ctrlKey){e.preventDefault();toggleGrounding(e.shiftKey?false:undefined);return;}if(key==='h'){e.preventDefault();if(e.shiftKey){isolated=null;update();}else isolateSelection();return;}if(key==='w'||key==='e'){manipulation=key==='w'?'move':'rotate';renderInspector();updateOutline();needsRender=true;return;}if(key==='c'&&tool==='build'&&!e.metaKey&&!e.ctrlKey&&!e.altKey){e.preventDefault();cycleConnection(e.shiftKey);return;}if(key==='tab'&&tool==='build'&&(pointerInside||catalogDrag?.active)){e.preventDefault();if(e.shiftKey){snapCycle++;updatePointer(lastMouse);}else{cyclePlacementPort();}return;}if(key==='escape'&&physicsGrab){endPhysicsGrab(true);return;}if(key===' '&&simulationOpen&&simulationTab==='balance'){e.preventDefault();$('#stability-run').click();return;}if(key===' '&&physicsOpen){e.preventDefault();physicsBody?stopPhysics():startPhysics();return;}if(key===' '&&model.parts.some(p=>definition(p).motor)){e.preventDefault();motorRunning?stopMotor():startMotor();return;}if((e.metaKey||e.ctrlKey)&&key==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if((e.metaKey||e.ctrlKey)&&key==='s'){e.preventDefault();$('#save').click();return;}if((e.metaKey||e.ctrlKey)&&key==='d'){e.preventDefault();if(selected)duplicatePicked();return;}if(key==='escape'&&gizmo?.dragging){gizmo.cancel();return;}if(key==='escape'){selected=null;setTool('select');renderCatalog();renderModelTree();updateOutline();}if(key==='v'){setTool('select');renderCatalog();}if(key==='b'){setTool('build');renderCatalog();}if(key==='f')frameSelection();if(key==='r'){if(tool==='build'){if(mode==='worm'){toast('Worm engagement has a fixed axle position.');return;}if(mode==='wedge'){toast('Keyed fit · fixed at 45°. Choose another recess or face.');return;}roll=(roll+(e.shiftKey?-45:45))%360;renderInspector();refreshGhost();}else rotatePicked(e.shiftKey?-45:45);}if(key==='delete'||key==='backspace'){e.preventDefault();removeSelected();}if(key==='/'){e.preventDefault();$('#search').focus();}});
gizmo=createGizmo({stage:$('.stage'),camera:()=>camera,state:motionState,start:startMotion,change:dragMotion,finish:finishMotion});
function animate(time=0){requestAnimationFrame(animate);const dt=lastFrame?Math.min(.05,(time-lastFrame)/1000):0;lastFrame=time;if(driveView||controllerRunning)tickController(dt);if(motorRunning&&dt){try{const step=stepMotor(model,motorId,dt,{rpm:motorRpm,direction:motorDirection});motorAngle=(motorAngle+step.degrees)%360;if(definition(model.parts.find(p=>p.id===motorId)).springMotor){$('#spring-charge').textContent=model.parts.find(p=>p.id===motorId).springTurns.toFixed(2)+' turns wound';if(step.exhausted)stopMotor();}syncPartTransforms();$('#motor-angle').textContent=motorAngle.toFixed(1)+'°';}catch(e){stopMotor();toast(e.message);}}if(physicsBody&&dt){if(physicsBody.kind==='hinge-system'){stepHingeSystem(model,physicsBody,dt);$('#physics-angle').textContent=physicsBody.jointCount+(physicsBody.ballCount?' joints':' hinges');}else{stepPhysics(model,physicsBody,dt);$('#physics-angle').textContent=(physicsBody.angle/DEG).toFixed(1)+'°';}syncPartTransforms();}unified?.tick(dt);stabilityUI?.tick(time,dt);controls.update();if(needsRender){gizmo?.render();renderer.render(scene,camera);needsRender=false;}}const repeatUI=patternUI({getModel:()=>model,getIds:()=>syncSelection(),toast,commit:(next,ids)=>{snapshot();model=next;selection=new Set(ids);selected=ids[0];isolated=null;update();}});
$('#disconnect-selection').onclick=disconnectPicked;$('#reconnect-selection').onclick=reconnectPicked;$('#clone-selection').onclick=duplicatePicked;$('#pattern-selection').onclick=()=>repeatUI.open();
createRadialMenu(renderer.domElement,{title:()=>selection.size?selection.size+' selected':'Workspace',onOpen:e=>{if(unified?.active)return false;stabilityUI?.stop();stopController();stopPhysics();stopMotor();if(e.type!=='keydown'){const id=canvasPick(e);if(id&&!selection.has(id))selectIds(e.altKey?[id]:groupFor(model,id)?.partIds||[id]);}},items:()=>selection.size?[
{label:'Move',icon:'move',key:'W',run:()=>$('#move-selection').click()},
{label:'Rotate',icon:'rotate',key:'E',run:()=>$('#rotate-selection').click()},
{label:'Repeat +',icon:'repeat',run:()=>repeatUI.open()},
{label:'Clone',icon:'clone',key:'⌘D',run:duplicatePicked},
{label:groundedParts(model,selection).length===selection.size?'Unlock':'Lock',icon:'ground',key:'G',run:()=>toggleGrounding()},
{label:externalLinks(model,selection).length?'Disconnect':'Reconnect',icon:'disconnect',run:()=>externalLinks(model,selection).length?disconnectPicked():reconnectPicked()},
{label:'Simulate',icon:'physics',run:()=>openSimulation('balance')},
{label:'Frame',icon:'frame',key:'F',run:frameSelection}
]:[{label:'Place part',icon:'add',key:'B',run:()=>{setTool('build');renderCatalog();}},{label:'Examples',icon:'examples',run:showExamples},{label:'Generate',icon:'repeat',run:()=>$('#generate').click()},{label:'Fit model',icon:'frame',key:'F',run:fit}]});
const partLibrary=createPartLibrary({root:$('#catalog'),parts:CATALOG.filter(d=>!d.legacy),icon:iconSVG,choose:chooseType,active:()=>tool==='build'?type:null});
$('.tabs').hidden=true;
decorateTools();
unified=physicsWorkspace({scene,renderer,getCamera:()=>camera,getControls:()=>controls,partsGroup,getModel:()=>model,getSelection:()=>selection,commit:fn=>{snapshot();fn(model);update();},redraw:()=>{needsRender=true;},stopOthers:()=>{stabilityUI?.toggle(false);stopController();stopPhysics();stopMotor();clearGhost();markerGroup.clear();partLibrary?.close();},onActive:value=>{if(value){simulationOpen=false;physicsOpen=false;document.body.classList.remove('simulation-open');}document.querySelectorAll('.topbar,.library,.selection-tools,.toolbar>*:not(#simulation-tool):not(#view-controls):not(#fit)').forEach(e=>e.inert=value);$('#simulation-tool').setAttribute('aria-pressed',String(value));$('#simulation-panel').hidden=true;if(!value){renderMarkers();updateOutline();}else{for(const box of [outline,motionOutline,groundOutline])if(box)box.visible=false;gizmo?.hide?.();}needsRender=true;},loadExample});
stabilityUI=createStabilityUI({scene,getModel:()=>model,getSelected:()=>selected,stopOthers:()=>{stopController();stopPhysics();stopMotor();},changed:()=>update(),sync:()=>syncPartTransforms(),record:before=>{history.push(before);if(history.length>80)history.shift();future=[];},restore:next=>{model=next;},redraw:()=>{needsRender=true;},toast,onRunning:value=>{tippingActive=value;updateOutline();needsRender=true;},loadExample});renderCatalog();update();resize();fit();animate();
// Read-only diagnostic state supports repeatable UI verification without altering models.
window.knexDiagnostics=()=>({parts:model.parts.length,links:model.links.length,selected,tool,mode,type,markers:markerGroup.children.length,ghost:!!ghost,renderer:renderer.info.render,model:JSON.parse(exportModel(model))});

function renderMassPanel(root,p){const d=definition(p),spec=PART_SPECS[p.type],panel=document.createElement('details');panel.className='mass-panel';panel.innerHTML=`<summary>Weight &amp; payload</summary><label>Part + payload mass (g)<input id="part-mass" aria-label="Part and payload mass in grams" type="number" min="0.001" max="100000" step="1" value="${partMass(p,d).toFixed(3)}"></label><p class="note">${p.massG!==undefined?'Assigned test mass':spec?'Supplier approximate mass':'Estimated part mass'}. Include payload${d.motor?' and batteries':''} in this value. ${spec?`<a href="${spec.source}" target="_blank" rel="noreferrer">Part ${spec.partNumber} source</a>`:'No verified weight source.'}${d.motor?' Supplier battery inclusion in weight is unspecified.':''}</p><button id="mass-default">Use default mass</button><details><summary>Local center of mass (mm)</summary><div class="axis-grid">${['X','Y','Z'].map((a,i)=>`<label>${a}<input data-mass-center="${i}" aria-label="Local mass center ${a}" type="number" min="-1000" max="1000" value="${localMassCenter(p,d)[i]}"></label>`).join('')}</div><p class="note">Relative to this part, before its rotation. Default location is approximate.</p></details><button id="show-stability">Show weight &amp; stability</button>`;root.prepend(panel);$('#part-mass').onchange=e=>{const value=Number(e.target.value);if(!Number.isFinite(value)||value<=0||value>100000){toast('Enter a mass above 0 and at most 100000 g.');renderInspector();return;}snapshot();p.massG=value;update();};$('#mass-default').onclick=()=>{snapshot();delete p.massG;delete p.massCenter;update();};$$('[data-mass-center]').forEach(input=>input.onchange=()=>{const value=Number(input.value);if(!Number.isFinite(value)||Math.abs(value)>1000){toast('Use a local center between -1000 and 1000 mm.');renderInspector();return;}snapshot();p.massCenter=[...localMassCenter(p,d)];p.massCenter[Number(input.dataset.massCenter)]=value;update();});$('#show-stability').onclick=()=>openSimulation('balance');}
